import { act, cleanup, fireEvent, render, screen, within } from '@testing-library/react'
import { afterEach, expect, test, vi } from 'vitest'
import AlgorithmsLab from './AlgorithmsLab'
import type { AlgorithmInfo, LabExecution, LabState } from '../../lib/algorithms'

// Small software fixtures. Production traces are generated by Python.
const info: AlgorithmInfo = {
  id: 'bubble-sort', name: 'Bubble Sort', category: 'Sorting', visual: 'bars',
  description: 'Adjacent comparisons.', how: 'Swap inversions.', input: 'Integers.', output: 'Sorted values.',
  time: 'O(n²)', space: 'O(1)', advantages: 'Stable.', limitations: 'Quadratic.', use_case: 'Educational ordering.',
  pseudocode: ['initialize', 'compare', 'swap', 'finish'], operations: [], example: { algorithm: 'bubble-sort', values: [2, 1] },
}
const stack: AlgorithmInfo = { ...info, id: 'stack', name: 'Stack', category: 'Data structures', visual: 'stack',
  operations: [{ action: 'push', fields: ['value'], time: 'O(1)' }, { action: 'pop', fields: [], time: 'O(1)' }],
  example: { algorithm: 'stack', values: [], operations: [] } }
const state: LabState = { values: [2, 1], nodes: [], edges: [], directed: false, slots: [], head: null, tail: null, buckets: [], priorities: [] }
const base = { state, active: [], completed: [], range: null, current: null, visited: [], frontier: [], distances: {}, path_edges: [], error: false }
const trace: LabExecution = { step_count: 3, runs: [{ algorithm: 'bubble-sort',
  metrics: { comparisons: 1, swaps: 1, writes: 2, operations: 0 }, result: { values: [1, 2] },
  steps: [{ ...base, line: 1, message: 'Initial values' }, { ...base, line: 2, message: 'Compare values', active: [0, 1] },
    { ...base, line: 4, message: 'Sorting complete', state: { ...state, values: [1, 2] }, completed: [0, 1] }],
}] }

function api(execute: () => Promise<Response> = async () => Response.json(trace)) {
  const post = vi.fn(execute)
  vi.stubGlobal('fetch', vi.fn(async (url: string) => url === '/api/v1/algorithms' ? Response.json([info, stack]) : post()))
  return post
}
afterEach(() => { cleanup(); vi.unstubAllGlobals(); vi.useRealTimers() })

test('Run, Pause, Reset, Step Forward and speed control actual returned frames', async () => {
  const post = api()
  render(<AlgorithmsLab />)
  await screen.findByRole('heading', { name: 'Bubble Sort', level: 2 })
  expect(post).not.toHaveBeenCalled()
  fireEvent.click(screen.getByRole('button', { name: 'Run' }))
  await screen.findByLabelText('Bubble Sort execution')
  fireEvent.click(screen.getByRole('button', { name: 'Pause' }))
  vi.useFakeTimers()
  const status = () => screen.getByText(/Step \d+ of/).textContent
  expect(status()).toContain('Step 1 of 3')
  fireEvent.click(screen.getByRole('button', { name: 'Run' }))
  await act(() => vi.advanceTimersByTimeAsync(800))
  expect(status()).toContain('Step 2 of 3')
  fireEvent.click(screen.getByRole('button', { name: 'Pause' }))
  await act(() => vi.advanceTimersByTimeAsync(2000))
  expect(status()).toContain('Step 2 of 3')
  fireEvent.change(screen.getByLabelText('Animation speed'), { target: { value: '4' } })
  fireEvent.click(screen.getByRole('button', { name: 'Run' }))
  await act(() => vi.advanceTimersByTimeAsync(200))
  expect(status()).toContain('Step 3 of 3 · Complete')
  expect(screen.getByLabelText('Bubble Sort recorded work').textContent).toContain('comparisons1')
  fireEvent.click(screen.getByRole('button', { name: 'Reset' }))
  expect(status()).toContain('Step 1 of 3')
  fireEvent.click(screen.getByRole('button', { name: 'Step Forward' }))
  expect(status()).toContain('Step 2 of 3')
  expect(post).toHaveBeenCalledOnce()
  expect(screen.getByText('compare').closest('li')?.getAttribute('aria-current')).toBe('step')
})

test('invalid custom inputs do not execute and API errors support retry', async () => {
  let attempts = 0
  const post = api(async () => ++attempts === 1 ? Response.json({ detail: 'Invalid test input' }, { status: 422 }) : Response.json(trace))
  render(<AlgorithmsLab />)
  await screen.findByLabelText('Values')
  fireEvent.change(screen.getByLabelText('Values'), { target: { value: '1, oops' } })
  fireEvent.click(screen.getByRole('button', { name: 'Run' }))
  expect(screen.getByRole('alert').textContent).toContain('integers')
  expect(post).not.toHaveBeenCalled()
  fireEvent.change(screen.getByLabelText('Values'), { target: { value: '2, 1' } })
  fireEvent.click(screen.getByRole('button', { name: 'Run' }))
  expect((await screen.findByRole('alert')).textContent).toContain('Invalid test input')
  fireEvent.click(screen.getByRole('button', { name: 'Retry execution' }))
  expect(await screen.findByLabelText('Bubble Sort execution')).toBeTruthy()
})

test('structure operations can be configured and changing algorithms clears prior playback', async () => {
  api()
  render(<AlgorithmsLab />)
  await screen.findByLabelText('Category')
  fireEvent.change(screen.getByLabelText('Category'), { target: { value: 'Data structures' } })
  expect(screen.getByRole('heading', { name: 'Stack', level: 2 })).toBeTruthy()
  fireEvent.change(screen.getByLabelText('Operation value'), { target: { value: '7' } })
  fireEvent.click(screen.getByRole('button', { name: 'Add operation' }))
  expect(within(screen.getByLabelText('Queued operations')).getByText(/"value":7/)).toBeTruthy()
  fireEvent.click(screen.getByRole('button', { name: 'Remove operation 1' }))
  expect(screen.getByLabelText('Queued operations').textContent).toBe('')
  expect(screen.queryByLabelText('Bubble Sort execution')).toBeNull()
})
